constexpr double Pi=3.1415926535897932384626433832795,TwoPi=Pi*2.0;
struct Motion {double x{},y{},z{},yaw{};};
bool Finite(float v)noexcept{return std::isfinite(v);}
bool Finite(Vec3 v)noexcept{return Finite(v.x)&&Finite(v.y)&&Finite(v.z);}
bool Finite(const Matrix4& m)noexcept{for(const auto& row:m.values)for(float v:row)if(!Finite(v))return false;return true;}
double NormalizeYaw(double value)noexcept{value=std::fmod(value,TwoPi);if(value>Pi)value-=TwoPi;if(value<=-Pi)value+=TwoPi;return value;}
Motion Compose(Motion a,Motion b)noexcept{const double c=std::cos(a.yaw),s=std::sin(a.yaw);return{a.x+c*b.x+s*b.z,a.y+b.y,a.z-s*b.x+c*b.z,NormalizeYaw(a.yaw+b.yaw)};}
