bool Finite(Motion v)noexcept{return std::isfinite(v.x)&&std::isfinite(v.y)&&std::isfinite(v.z)&&std::isfinite(v.yaw);}
Quaternion3D Rotation(const JointTransform3D& value)noexcept{return value.usesQuaternion?NormalizeQuaternion3D(value.quaternion):QuaternionFromEuler3D(value.rotation);}
Quaternion3D Multiply(Quaternion3D l,Quaternion3D r)noexcept{return NormalizeQuaternion3D({l.w*r.x+l.x*r.w+l.y*r.z-l.z*r.y,l.w*r.y-l.x*r.z+l.y*r.w+l.z*r.x,l.w*r.z+l.x*r.y-l.y*r.x+l.z*r.w,l.w*r.w-l.x*r.x-l.y*r.y-l.z*r.z});}
Quaternion3D YawQuaternion(double yaw)noexcept{const float half=float(yaw*.5);return{0,std::sin(half),0,std::cos(half)};}
double Yaw(const JointTransform3D& value)noexcept{const Matrix4 m=value.Matrix();return std::atan2(double(m[0][2]),double(m[2][2]));}
const AnimationTrack3D* RootTrack(const AnimationClip3D& clip,std::size_t root)noexcept{for(const auto& track:clip.tracks)if(track.joint==root)return &track;return nullptr;}
bool ValidRootTrack(const AnimationTrack3D* track,double duration)noexcept{if(!track)return true;if(track->keyframes.empty()||track->keyframes.front().time!=0.f||track->keyframes.back().time!=float(duration))return false;float previous=-1;for(const auto& frame:track->keyframes){if(frame.time<=previous)return false;previous=frame.time;}return true;}
