bool RootMotion3D::Prepare(const Skeleton3D& skeleton,const HumanoidSkeletonMap3D& map,SkeletonCompatibilityId3D expected,const AnimationClip3D& clip,RootMotionSettings3D settings){if(!expected||!settings.maximumCyclesPerTick||skeleton.joints.size()>MaximumJoints||!map.Valid(skeleton,expected)||skeleton.joints[map.Joint(HumanoidJoint3D::Root)].parent!=-1||!clip.Valid(skeleton)||!RootMotionInternal::ValidateRootTrack(clip,map.Joint(HumanoidJoint3D::Root)))return false;try{AnimationPose3D active,pending;active.localTransforms.resize(skeleton.joints.size());active.globalMatrices.resize(skeleton.joints.size());pending.localTransforms.resize(skeleton.joints.size());pending.globalMatrices.resize(skeleton.joints.size());AnimationClip3D owned=clip;Skeleton3D ownedSkeleton=skeleton;scratch_=std::move(active);previewScratch_=std::move(pending);clip_=std::move(owned);skeleton_=std::move(ownedSkeleton);settings_=settings;compatibility_=expected;jointCount_=skeleton.joints.size();rootJoint_=map.Joint(HumanoidJoint3D::Root);Reset();return true;}catch(...){return false;}}
