    auto fail=[](RootMotionStatus3D){return false;};if(previewPending_||generation_==(std::numeric_limits<std::uint64_t>::max)()||previewSerial_==(std::numeric_limits<std::uint64_t>::max)())return false;if(!compatibility_||jointCount_!=skeleton.joints.size()||jointCount_>MaximumJoints||rootJoint_>=jointCount_||skeleton.joints[rootJoint_].parent!=-1||!SameSkeleton(skeleton,skeleton_))return fail(RootMotionStatus3D::InvalidRig);if(lastTick_==(std::numeric_limits<std::uint64_t>::max)()||tick.tick!=lastTick_+1)return fail(RootMotionStatus3D::DiscontinuousTick);if(!std::isfinite(tick.time)||!Finite(tick.poseRoot))return fail(RootMotionStatus3D::InvalidTime);const auto* track=RootTrack(clip_,rootJoint_);if(!clip_.Valid(skeleton)||!ValidRootTrack(track,clip_.duration))return fail(RootMotionStatus3D::InvalidClip);std::int64_t currentCycle{};if(clip_.looping&&!Cycle(tick.time,clip_.duration,currentCycle))return fail(RootMotionStatus3D::Limit);if(pose.localTransforms.size()!=jointCount_||pose.globalMatrices.size()!=jointCount_||previewScratch_.localTransforms.size()!=jointCount_||previewScratch_.globalMatrices.size()!=jointCount_||!PoseFinite(pose))return fail(RootMotionStatus3D::InvalidPose);
