    const double duration=clip_.duration,clamped=clip_.looping?tick.time:std::clamp(tick.time,0.0,duration),wrapped=clip_.looping?Phase(clamped,duration):clamped;const JointTransform3D current=Sample(skeleton,track,rootJoint_,wrapped);if(!Near(pose.localTransforms[rootJoint_],current))return fail(RootMotionStatus3D::InvalidPose);Motion motion{};std::int64_t crossed{};if(anchored_){RootMotionInternal::Motion3D extracted{};if(!RootMotionInternal::ExtractInterval(skeleton,clip_,rootJoint_,lastTime_,clamped,settings_.maximumCyclesPerTick,settings_.extractVertical,extracted,crossed))return fail(RootMotionStatus3D::Limit);motion={extracted.x,extracted.y,extracted.z,extracted.yaw};if(!Finite(motion))return fail(RootMotionStatus3D::Limit);}
    const JointTransform3D reference=Sample(skeleton,track,rootJoint_,0);JointTransform3D candidateRoot=pose.localTransforms[rootJoint_];candidateRoot.translation.x=reference.translation.x;candidateRoot.translation.z=reference.translation.z;if(settings_.extractVertical)candidateRoot.translation.y=reference.translation.y;const double wrappedYawDelta=NormalizeYaw(Yaw(current)-Yaw(reference));candidateRoot.quaternion=Multiply(YawQuaternion(-wrappedYawDelta),Rotation(candidateRoot));candidateRoot.usesQuaternion=true;if(!Finite(candidateRoot.quaternion.x)||!Finite(candidateRoot.quaternion.y)||!Finite(candidateRoot.quaternion.z)||!Finite(candidateRoot.quaternion.w))return fail(RootMotionStatus3D::InvalidPose);std::array<Matrix4,MaximumJoints> candidateGlobals{};for(std::size_t i=0;i<jointCount_;++i){const JointTransform3D& local=i==rootJoint_?candidateRoot:pose.localTransforms[i];const int parent=skeleton.joints[i].parent;candidateGlobals[i]=parent<0?tick.poseRoot*local.Matrix():candidateGlobals[std::size_t(parent)]*local.Matrix();if(!Finite(candidateGlobals[i]))return fail(RootMotionStatus3D::InvalidPose);}
