bool RootMotion3D::EvaluateTick(const Skeleton3D& skeleton,RootMotionTick3D tick,AnimationPose3D& pose,RootMotionResult3D* output)noexcept{InvalidatePreview(false);RootMotionPreviewToken3D token{};RootMotionResult3D result{};if(!PreviewTick(skeleton,tick,pose,token,&result)||!CanCommitPreview(token,pose)){CancelPreview(token);return false;}CommitPreviewUnchecked(token,pose);if(output)*output=result;return true;}
bool RootMotion3D::CanCommitPreview(const RootMotionPreviewToken3D& token,const AnimationPose3D& pose)const noexcept{return previewPending_&&token.valid&&token.owner==reinterpret_cast<std::uintptr_t>(this)&&token.pose==&pose&&token.generation==generation_&&token.serial==previewSerial_&&token.tick==previewResult_.delta.tick&&token.baseStateHash==previewBaseStateHash_&&token.poseHash==PoseHash(pose)&&token.candidateHash==previewResult_.delta.deterministicHash;}
bool RootMotion3D::CancelPreview(RootMotionPreviewToken3D& token)noexcept{if(!previewPending_||!token.valid||token.owner!=reinterpret_cast<std::uintptr_t>(this)||token.serial!=previewSerial_)return false;previewPending_=false;token={};return true;}
void RootMotion3D::CommitPreviewUnchecked(RootMotionPreviewToken3D& token,AnimationPose3D& pose)noexcept{scratch_.localTransforms.swap(previewScratch_.localTransforms);scratch_.globalMatrices.swap(previewScratch_.globalMatrices);for(std::size_t i=0;i<jointCount_;++i){pose.localTransforms[i]=scratch_.localTransforms[i];pose.globalMatrices[i]=scratch_.globalMatrices[i];}lastTick_=previewResult_.delta.tick;lastTime_=previewLastTime_;anchored_=true;previewPending_=false;++generation_;token={};}
void RootMotion3D::InvalidatePreview(bool committedMutation)noexcept{previewPending_=false;if(committedMutation&&generation_!=(std::numeric_limits<std::uint64_t>::max)())++generation_;}
void RootMotion3D::Reset()noexcept{InvalidatePreview(true);anchored_=false;lastTick_=0;lastTime_=0;}
bool RootMotion3D::CanTeleport(std::uint64_t previousTick)const noexcept{return compatibility_&&jointCount_&&previousTick!=(std::numeric_limits<std::uint64_t>::max)();}
bool RootMotion3D::Teleport(std::uint64_t previousTick)noexcept{if(!CanTeleport(previousTick))return false;InvalidatePreview(true);anchored_=false;lastTick_=previousTick;lastTime_=0;return true;}
std::size_t RootMotion3D::TrimUnusedMemory(){const auto before=MemoryStats().retainedCapacityBytes;AnimationPose3D active,pending;scratch_.localTransforms.swap(active.localTransforms);scratch_.globalMatrices.swap(active.globalMatrices);previewScratch_.localTransforms.swap(pending.localTransforms);previewScratch_.globalMatrices.swap(pending.globalMatrices);AnimationClip3D clip;clip_.tracks.swap(clip.tracks);Skeleton3D skeleton;skeleton_.joints.swap(skeleton.joints);compatibility_={};jointCount_=rootJoint_=0;Reset();lastReleasedBytes_=before;++trimCount_;return before;}
ReusableMemoryStats RootMotion3D::MemoryStats()const noexcept{std::size_t bytes=(scratch_.localTransforms.capacity()+previewScratch_.localTransforms.capacity())*sizeof(JointTransform3D)+(scratch_.globalMatrices.capacity()+previewScratch_.globalMatrices.capacity())*sizeof(Matrix4)+clip_.tracks.capacity()*sizeof(AnimationTrack3D)+skeleton_.joints.capacity()*sizeof(SkeletonJoint3D);for(const auto& track:clip_.tracks)bytes+=track.keyframes.capacity()*sizeof(AnimationKeyframe3D);return{bytes,jointCount_?0:bytes,lastReleasedBytes_,trimCount_};}
